package com.isoform

import com.facebook.react.module.annotations.ReactModule
import com.facebook.react.uimanager.SimpleViewManager
import com.facebook.react.uimanager.ThemedReactContext
import com.facebook.react.uimanager.ViewManagerDelegate
import com.facebook.react.uimanager.annotations.ReactProp
import com.facebook.react.viewmanagers.IsoPdfViewManagerDelegate
import com.facebook.react.viewmanagers.IsoPdfViewManagerInterface

/**
 * Bridge between Fabric and `IsoPdfView`: props, commands and events.
 * `IsoPdfViewManagerInterface`/`Delegate` are generated by Codegen from
 * `src/adapters/react-native/media/pdf/native/IsoPdfViewNativeComponent.ts`.
 */
@ReactModule(name = IsoPdfViewManager.NAME)
class IsoPdfViewManager :
  SimpleViewManager<IsoPdfView>(),
  IsoPdfViewManagerInterface<IsoPdfView> {

  private val delegate = IsoPdfViewManagerDelegate(this)

  override fun getDelegate(): ViewManagerDelegate<IsoPdfView> = delegate

  override fun getName(): String = NAME

  override fun createViewInstance(context: ThemedReactContext): IsoPdfView = IsoPdfView(context)

  override fun onDropViewInstance(view: IsoPdfView) {
    view.release()
    super.onDropViewInstance(view)
  }

  // ── props ──

  @ReactProp(name = "src")
  override fun setSrc(view: IsoPdfView, value: String?) = view.setSource(value)

  @ReactProp(name = "password")
  override fun setPassword(view: IsoPdfView, value: String?) = view.setPassword(value)

  @ReactProp(name = "initialPage", defaultInt = 1)
  override fun setInitialPage(view: IsoPdfView, value: Int) = view.setInitialPage(value)

  @ReactProp(name = "controls", defaultBoolean = true)
  override fun setControls(view: IsoPdfView, value: Boolean) = view.setControls(value)

  @ReactProp(name = "nightMode")
  override fun setNightMode(view: IsoPdfView, value: Boolean) = view.setNightMode(value)

  @ReactProp(name = "fit")
  override fun setFit(view: IsoPdfView, value: String?) = view.setFit(value)

  @ReactProp(name = "direction")
  override fun setDirection(view: IsoPdfView, value: String?) = view.setDirection(value)

  @ReactProp(name = "maxZoom", defaultFloat = 5f)
  override fun setMaxZoom(view: IsoPdfView, value: Float) = view.setMaxZoom(value)

  @ReactProp(name = "playlistIndex", defaultInt = -1)
  override fun setPlaylistIndex(view: IsoPdfView, value: Int) = view.setPlaylist(value, view.playlistCount)

  @ReactProp(name = "playlistCount")
  override fun setPlaylistCount(view: IsoPdfView, value: Int) = view.setPlaylist(view.playlistIndex, value)

  @ReactProp(name = "speechLanguage")
  override fun setSpeechLanguage(view: IsoPdfView, value: String?) = view.setSpeechLanguage(value)

  @ReactProp(name = "speechVoice")
  override fun setSpeechVoice(view: IsoPdfView, value: String?) = view.setSpeechVoice(value)

  // ── commands ──

  override fun goToPage(view: IsoPdfView, page: Int) = view.goToPage(page)

  override fun search(view: IsoPdfView, query: String) = view.search(query)

  override fun searchNext(view: IsoPdfView) = view.searchNext()

  override fun searchPrevious(view: IsoPdfView) = view.searchPrevious()

  override fun clearSearch(view: IsoPdfView) = view.clearSearch()

  override fun setZoom(view: IsoPdfView, scale: Float) = view.setZoom(scale)

  override fun setFullscreen(view: IsoPdfView, fullscreen: Boolean) = view.setFullscreen(fullscreen)

  override fun startReadAloud(view: IsoPdfView) = view.startReadAloud()

  override fun stopReadAloud(view: IsoPdfView) = view.stopReadAloud()

  // ── events (native name → JS prop) ──

  override fun getExportedCustomDirectEventTypeConstants(): Map<String, Any> =
    IsoPdfView.EVENTS.associateWith { mapOf("registrationName" to "on" + it.removePrefix("top")) }

  companion object {
    const val NAME = "IsoPdfView"
  }
}
